// Error travels by explicit return. Swallowing proceeds on garbage.
function bottom() { return { data: 'garbage', err: 'disk gone' }; }
function forward() {
  const r = bottom();
  if (r.err !== null && r.err !== undefined) return 'stopped, reported: ' + r.err;
  return 'used: ' + r.data;
}
function swallow() {
  const r = bottom();
  return 'used: ' + r.data; // err ignored
}
console.log('forward: ' + forward());
console.log('swallow: ' + swallow());
